    <script>let accountForm=null;function accountHidden(name,value){const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;return input}function openAccountSecurityModal(form,title,reset){accountForm=form;document.getElementById('account-security-title').textContent=title;document.getElementById('account-new-passwords').classList.toggle('hidden',!reset);document.getElementById('account-security-modal').classList.remove('hidden');document.getElementById('account-security-modal').classList.add('flex');document.getElementById('account-admin-password').focus()}function closeAccountSecurityModal(){document.getElementById('account-security-modal').classList.add('hidden');document.getElementById('account-security-modal').classList.remove('flex');accountForm=null}function submitAccountSecurityModal(){if(!accountForm)return;accountForm.appendChild(accountHidden('admin_password',document.getElementById('account-admin-password').value));if(!document.getElementById('account-new-passwords').classList.contains('hidden')){accountForm.appendChild(accountHidden('password',document.getElementById('account-new-password').value));accountForm.appendChild(accountHidden('password_confirmation',document.getElementById('account-new-password-confirmation').value))}accountForm.submit()}</script>
