entById('salary-method')?.addEventListener('change',syncSalaryMethod);function submitSalaryPayment(){if(!salaryForm)return;[['payment_method','salary-method'],['payment_phone','salary-phone'],['transaction_id','salary-transaction'],['bank_details','salary-bank']].forEach(([n,id])=>{const input=document.createElement('input');input.type='hidden';input.name=n;input.value=document.getElementById(id).value;salaryForm.appendChild(input)});salaryForm.submit()}</script>@endif
