<script>
function openSalaryReceipt(preview, download){const modal=document.getElementById('salary-receipt-modal');document.getElementById('salary-receipt-frame').src=preview;document.getElementById('salary-receipt-download').href=download;modal.classList.remove('hidden');modal.classList.add('flex')}
function closeSalaryReceipt(){const modal=document.getElementById('salary-receipt-modal');modal.classList.add('hidden');modal.classList.remove('flex');document.getElementById('salary-receipt-frame').src=''}
function printSalaryReceipt(){document.getElementById('salary-receipt-frame').contentWindow?.print()}
let salaryCancelForm=null;
function openSalaryCancel(form){salaryCancelForm=form;const modal=document.getElementById('salary-cancel-modal');modal.classList.remove('hidden');modal.classList.add('flex')}
function closeSalaryCancel(){const modal=document.getElementById('salary-cancel-modal');modal.classList.add('hidden');modal.classList.remove('flex');salaryCancelForm=null}
function confirmSalaryCancel(){if(salaryCancelForm)salaryCancelForm.submit()}
@if(session('salary_receipt')) document.addEventListener('DOMContentLoaded',()=>openSalaryReceipt(@json(session('salary_receipt.preview')),@json(session('salary_receipt.download')))); @endif
document.addEventListener('DOMContentLoaded',()=>{
    const salaryReceiptLinks=@json($salaryReceiptLinks);
    document.querySelectorAll('form[action*="/salary"] label span').forEach(span=>span.addEventListener('click',event=>{
        const form=span.closest('form'); const month=form?.querySelector('[name="month"]')?.value; const receipt=salaryReceiptLinks[month];
        if(!receipt)return; event.preventDefault(); event.stopPropagation(); openSalaryReceipt(receipt.preview,receipt.download);
    }));
    document.querySelectorAll('form[action*="/salary"] input[type="checkbox"]').forEach(box=>box.dataset.wasPaid=box.checked?'1':'0');
    document.addEventListener('click',event=>{
        const box=event.target.closest('form[action*="/salary"] input[type="checkbox"]');
        if(!box || box.dataset.wasPaid!=='1')return;
        event.preventDefault();event.stopImmediatePropagation();openSalaryCancel(box.form);
    },true);
    const saved=@json(['method'=>$user->salary_payment_method,'phone'=>$user->salary_payment_phone,'bank'=>$user->salary_payment_bank_details]);
    const method=document.getElementById('salary-method');
    if(!method)return;
    if(saved.method) method.value=saved.method;
    document.getElementById('salary-phone').value=saved.phone||'';
    document.getElementById('salary-transaction').value='';
    document.getElementById('salary-bank').value=saved.bank||'';
    const paymentLabels={cash:@json(__('Cash')),mobile_money:@json(__('Mobile Money')),bank_transfer:@json(__('Bank transfer'))};
    const savedMessage=saved.method?`${@json(__('Saved information'))} : <strong>${paymentLabels[saved.method]}</strong>. ${@json(__('You can choose another payment method for this payment.'))}`:@json(__('The information from this first payment will be saved for the next payment.'));
    method.closest('.mt-4').insertAdjacentHTML('beforeend',`<div class="mt-4 rounded-lg bg-slate-50 p-3 text-xs text-slate-600">${savedMessage}<label class="mt-2 flex items-center gap-2 text-slate-700"><input id="salary-save-preference" type="checkbox" ${saved.method?'':'checked'}> ${@json(__('Save this information as the usual payment method'))}</label></div>`);
    syncSalaryMethod();
});
window.submitSalaryPayment=function(){
    if(!salaryForm)return;
    salaryForm.querySelectorAll('[data-salary-payment-field]').forEach(el=>el.remove());
    const values=[['payment_method','salary-method'],['payment_phone','salary-phone'],['transaction_id','salary-transaction'],['bank_details','salary-bank']];
    values.forEach(([name,id])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=document.getElementById(id).value;input.dataset.salaryPaymentField='1';salaryForm.appendChild(input)});
    const save=document.createElement('input');save.type='hidden';save.name='save_payment_preference';save.value=document.getElementById('salary-save-preference')?.checked?'1':'0';save.dataset.salaryPaymentField='1';salaryForm.appendChild(save);
    salaryForm.submit();
}
</script>
