<script>
document.addEventListener('DOMContentLoaded',()=>{
    document.querySelectorAll('form[action*="/salary"] input[type="checkbox"]').forEach(box=>{
        const form=box.form, paid=box.checked, parent=box.parentElement; box.remove();
        if(!paid){const button=document.createElement('button');button.type='button';button.className='rounded-md bg-emerald-700 px-2 py-1 text-xs font-semibold text-white';button.textContent=@json(__('Pay'));button.addEventListener('click',()=>openSalaryPayment(button));parent.appendChild(button)}
    });
});
window.openSalaryPayment=function(button){salaryForm=button?.closest('form');salaryBox=null;salaryPrevious=false;const modal=document.getElementById('salary-payment-modal');modal.classList.remove('hidden');modal.classList.add('flex');syncSalaryMethod()};
</script>
<script>
document.addEventListener('DOMContentLoaded',()=>{
    const modal=document.getElementById('salary-payment-modal');
    if(!modal || document.getElementById('salary-admin-password')) return;
    const actions=modal.querySelector('.mt-6');
    const field=document.createElement('label');
    field.className='mt-4 block text-sm text-slate-700';
    field.innerHTML=`{{ __('Administrator password') }}<input id="salary-admin-password" type="password" autocomplete="current-password" required class="mt-1 w-full rounded-lg border-slate-300">`;
    actions?.parentElement.querySelector('.mt-6')?.before(field);
});
window.submitSalaryPayment=function(){
    if(!salaryForm)return;
    const password=document.getElementById('salary-admin-password')?.value||'';
    if(!password){document.getElementById('salary-admin-password')?.focus();return}
    salaryForm.querySelectorAll('[data-salary-payment-field]').forEach(el=>el.remove());
    const values=[['payment_method','salary-method'],['payment_phone','salary-phone'],['transaction_id','salary-transaction'],['bank_details','salary-bank'],['admin_password','salary-admin-password']];
    values.forEach(([name,id])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=document.getElementById(id)?.value||'';input.dataset.salaryPaymentField='1';salaryForm.appendChild(input)});
    const save=document.createElement('input');save.type='hidden';save.name='save_payment_preference';save.value=document.getElementById('salary-save-preference')?.checked?'1':'0';save.dataset.salaryPaymentField='1';salaryForm.appendChild(save);
    salaryForm.submit();
};
</script>
